1	package meter
2	
3	import (
4		"sort"
5		"sync"
6		"time"
7	)
8	
9	// Service 是订阅、用量与账单的本地内存服务。
10	// 单个 *Service 可被多个 goroutine 并发使用：重复提交只会生效一次。
11	type Service struct {
12		mu       sync.Mutex
13		now      func() time.Time
14		accounts map[string]*account
15		plans    map[string]Plan
16	}
17	
18	type subRecord struct {
19		planID      string
20		terms       PlanTerms
21		activatedAt time.Time
22		// termsHistory 按生效月份升序记录每次换套餐后的条件；
23		// 首条为开通当月适用的开通快照。账单按账期从中取当时适用的条件。
24		termsHistory []termsEntry
25		// pending 尚未生效的换套餐安排，每账户至多一条；nil 表示无安排。
26		pending *PlanChange
27		// cancelEnd 已安排的终止时刻（取消请求时刻的下一个 UTC 自然月月初）。
28		// 非 nil 且尚未到达时为等待取消状态；到达后本订阅段终止并移入 history。
29		cancelEnd *time.Time
30		// endedAt 已终止订阅段的实际终止时刻；当前有效段为 nil。
31		endedAt *time.Time
32	}
33	
34	type eventRecord struct {
35		at     time.Time
36		qty    int64
37		period Month
38	}
39	
40	type billRecord struct {
41		bill Bill
42	}
43	
44	type paymentRecord struct {
45		period Month
46		amount int64
47	}
48	
49	type account struct {
50		id       string
51		sub      *subRecord
52		history  []*subRecord
53		events   map[string]eventRecord
54		usage    map[Month]int64
55		bills    map[Month]*billRecord
56		payments map[string]paymentRecord
57	}
58	
59	// NewService 创建一个以系统时钟判断“当前时刻”的服务。
60	func NewService() *Service {
61		return NewServiceWithClock(time.Now)
62	}
63	
64	// NewServiceWithClock 创建使用自定义时钟的服务，便于测试账期与截止时刻。
65	func NewServiceWithClock(now func() time.Time) *Service {
66		if now == nil {
67			now = time.Now
68		}
69		return &Service{
70			now:      now,
71			accounts: make(map[string]*account),
72			plans:    make(map[string]Plan),
73		}
74	}
75	
76	func (s *Service) nowUTC() time.Time {
77		return s.now().UTC()
78	}
79	
80	// CreateAccount 创建业务账户。账户标识必须非空且唯一。
81	func (s *Service) CreateAccount(id string) error {
82		if id == "" {
83			return invalidf("account id is empty")
84		}
85		s.mu.Lock()
86		defer s.mu.Unlock()
87		if _, ok := s.accounts[id]; ok {
88			return ErrAccountExists
89		}
90		s.accounts[id] = &account{
91			id:       id,
92			events:   make(map[string]eventRecord),
93			usage:    make(map[Month]int64),
94			bills:    make(map[Month]*billRecord),
95			payments: make(map[string]paymentRecord),
96		}
97		return nil
98	}
99	
100	func validatePlan(p Plan) error {
101		if p.ID == "" {
102			return invalidf("plan id is empty")
103		}
104		if p.MonthlyFee < 0 || p.IncludedUnits < 0 || p.OveragePrice < 0 {
105			return invalidf("plan %q has negative amount or quantity", p.ID)
106		}
107		if p.TaxRateBasisPoints < 0 || p.TaxRateBasisPoints > 10000 {
108			return invalidf("plan %q tax rate %d out of [0,10000]", p.ID, p.TaxRateBasisPoints)
109		}
110		return nil
111	}
112	
113	// CreatePlan 创建套餐。金额单位为分，税率为万分比且在 [0,10000]。
114	func (s *Service) CreatePlan(p Plan) error {
115		if err := validatePlan(p); err != nil {
116			return err
117		}
118		s.mu.Lock()
119		defer s.mu.Unlock()
120		if _, ok := s.plans[p.ID]; ok {
121			return ErrPlanExists
122		}
123		s.plans[p.ID] = p
124		return nil
125	}
126	
127	// UpdatePlan 更新套餐当前条件。只影响之后开通的订阅，
128	// 已开通订阅继续使用开通时保存的快照。
129	func (s *Service) UpdatePlan(p Plan) error {
130		if err := validatePlan(p); err != nil {
131			return err
132		}
133		s.mu.Lock()
134		defer s.mu.Unlock()
135		if _, ok := s.plans[p.ID]; !ok {
136			return ErrPlanNotFound
137		}
138		s.plans[p.ID] = p
139		return nil
140	}
141	
142	// Subscribe 为账户开通订阅，并保存当时的套餐条件快照。
143	// 每个账户只允许一份有效订阅；从 activatedAt 起接收用量，
144	// 首月仍收完整月费并提供完整额度。
145	//
146	// 订阅终止（按月取消到达终止时刻）后可用本入口重新开通：activatedAt 不得早于
147	// 上一段订阅的终止时刻；重新开通保存当时的套餐条件，当月仍收完整月费、给完整
148	// 额度。重新开通不重置账户内事件与付款标识，也不清除旧欠费。
149	func (s *Service) Subscribe(accountID, planID string, activatedAt time.Time) error {
150		if accountID == "" {
151			return invalidf("account id is empty")
152		}
153		if planID == "" {
154			return invalidf("plan id is empty")
155		}
156		if activatedAt.IsZero() {
157			return invalidf("activated at is zero")
158		}
159		s.mu.Lock()
160		defer s.mu.Unlock()
161		acc, ok := s.accounts[accountID]
162		if !ok {
163			return ErrAccountNotFound
164		}
165		now := s.nowUTC()
166		// 与其他入口保持一致：先让已到期的换套餐/取消落入历史。
167		s.settleLocked(acc, now)
168		plan, ok := s.plans[planID]
169		if !ok {
170			return ErrPlanNotFound
171		}
172		if acc.sub != nil {
173			return ErrSubscriptionExists
174		}
175		activated := activatedAt.UTC()
176		// 重新开通时刻不得早于上一段订阅的终止时刻。
177		if n := len(acc.history); n > 0 {
178			if activated.Before(*acc.history[n-1].endedAt) {
179				return ErrResubscribeBeforeEnd
180			}
181		}
182		acc.sub = &subRecord{
183			planID:      planID,
184			terms:       termsOf(plan),
185			activatedAt: activated,
186			termsHistory: []termsEntry{{
187				effective: MonthOf(activated),
188				terms:     termsOf(plan),
189			}},
190		}
191		return nil
192	}
193	
194	// nextMonth 返回 period 的下一个 UTC 自然月。
195	func nextMonth(period Month) Month {
196		return MonthOf(period.End())
197	}
198	
199	// settleLocked 让当前订阅段中已到生效时刻的换套餐安排落入条件历史，
200	// 并在到达取消终止时刻时把当前段标记终止、移入 acc.history。
201	// 到达月初零点（或终止时刻）即生效，无需先上报用量或生成账单；即使中间若干月
202	// 没有调用服务，再次进入时也会在此一次性补齐。调用时持有 s.mu。
203	func (s *Service) settleLocked(acc *account, now time.Time) {
204		sub := acc.sub
205		if sub == nil {
206			return
207		}
208		current := MonthOf(now)
209		for sub.pending != nil && !current.Before(sub.pending.EffectivePeriod) {
210			entry := termsEntry{
211				effective: sub.pending.EffectivePeriod,
212				terms:     sub.pending.Terms,
213			}
214			sub.termsHistory = append(sub.termsHistory, entry)
215			sub.planID = sub.pending.TargetPlanID
216			sub.terms = sub.pending.Terms
217			sub.pending = nil
218		}
219		if sub.cancelEnd != nil && !now.Before(*sub.cancelEnd) {
220			end := *sub.cancelEnd
221			sub.cancelEnd = nil
222			sub.pending = nil
223			sub.endedAt = &end
224			acc.history = append(acc.history, sub)
225			acc.sub = nil
226		}
227	}
228	
229	// activeSegmentAtLocked 返回覆盖时刻 at 的订阅段：activatedAt <= at < end。
230	// 优先检查当前段，再按时间倒序检查历史段。调用时持有 s.mu。
231	func activeSegmentAtLocked(acc *account, at time.Time) *subRecord {
232		if cur := acc.sub; cur != nil && !at.Before(cur.activatedAt) {
233			if cur.cancelEnd == nil || at.Before(*cur.cancelEnd) {
234				return cur
235			}
236		}
237		for i := len(acc.history) - 1; i >= 0; i-- {
238			h := acc.history[i]
239			if !at.Before(h.activatedAt) && at.Before(*h.endedAt) {
240				return h
241			}
242		}
243		return nil
244	}
245	
246	// termsForPeriod 在订阅段 sub 中返回指定账期当时适用的套餐条件快照。
247	// 条件历史按生效月份升序，取不晚于 period 的最后一条；
248	// 这样历史账单始终按该账期条件计算，不受后续换套餐影响。
249	func termsForPeriod(sub *subRecord, period Month) PlanTerms {
250		t := sub.termsHistory[0].terms
251		for _, e := range sub.termsHistory {
252			if period.Before(e.effective) {
253				break
254			}
255			t = e.terms
256		}
257		return t
258	}
259	
260	// segmentForBillingLocked 返回账期 period 应使用的订阅段：
261	// 该订阅段在该账期内确有覆盖（开通当月计入，终止当月不计入）。
262	// 完全无订阅覆盖的月份返回 nil。调用时持有 s.mu。
263	func segmentForBillingLocked(acc *account, period Month) *subRecord {
264		if cur := acc.sub; cur != nil && !period.Before(MonthOf(cur.activatedAt)) {
265			return cur
266		}
267		for i := len(acc.history) - 1; i >= 0; i-- {
268			h := acc.history[i]
269			if period.Before(MonthOf(h.activatedAt)) {
270				continue
271			}
272			if period.Before(MonthOf(*h.endedAt)) {
273				return h
274			}
275		}
276		return nil
277	}
278	
279	// SchedulePlanChange 安排账户从下一个 UTC 自然月起改用另一套餐，升级与降级规则相同。
280	//
281	// 成功时返回目标套餐在本次安排时的完整计费条件快照与生效账期（请求被接受时的
282	// 下一个 UTC 自然月），之后修改套餐定义不影响本安排。当前月仍按旧套餐收取完整
283	// 月费并提供完整额度，不按天补差，也不迁移本月已发生的用量。
284	//
285	// 每个账户至多保留一条尚未生效的安排：再次安排同一目标套餐时返回原安排，
286	// 不重新取价（Created 为 false）；安排另一目标套餐则替换原安排，生效月份仍为
287	// 本次请求被接受时的下一月。欠费停用期间也可以安排。
288	//
289	// 账户不存在、尚未开通订阅、开通时刻尚未到达、目标套餐不存在、目标套餐与当前
290	// 生效套餐相同时请求失败，原有安排保持不变。登记取消订阅会清除尚未生效的安排，
291	// 等待取消期间安排换套餐失败（ErrPlanChangeWhileCancelling）。
292	func (s *Service) SchedulePlanChange(accountID, targetPlanID string) (PlanChangeResult, error) {
293		if accountID == "" {
294			return PlanChangeResult{}, invalidf("account id is empty")
295		}
296		if targetPlanID == "" {
297			return PlanChangeResult{}, invalidf("target plan id is empty")
298		}
299		s.mu.Lock()
300		defer s.mu.Unlock()
301	
302		acc, ok := s.accounts[accountID]
303		if !ok {
304			return PlanChangeResult{}, ErrAccountNotFound
305		}
306		now := s.nowUTC()
307		// 先让已到期的安排/取消生效：例如跨月后的首次调用，此时“当前套餐”已是新套餐；
308		// 恰在换套餐生效的月初登记取消，先承认该次切换，取消从再下一月生效。
309		s.settleLocked(acc, now)
310		if acc.sub == nil {
311			return PlanChangeResult{}, ErrSubscriptionNotFound
312		}
313		if now.Before(acc.sub.activatedAt) {
314			return PlanChangeResult{}, ErrSubscriptionNotActivated
315		}
316		if acc.sub.cancelEnd != nil {
317			return PlanChangeResult{}, ErrPlanChangeWhileCancelling
318		}
319	
320		plan, ok := s.plans[targetPlanID]
321		if !ok {
322			return PlanChangeResult{}, ErrPlanNotFound
323		}
324		if targetPlanID == acc.sub.planID {
325			return PlanChangeResult{}, ErrPlanChangeSamePlan
326		}
327	
328		// 已有安排且目标相同：原样返回，不重新取价。
329		if acc.sub.pending != nil && acc.sub.pending.TargetPlanID == targetPlanID {
330			return PlanChangeResult{Created: false, Change: *acc.sub.pending}, nil
331		}
332	
333		change := PlanChange{
334			TargetPlanID:    targetPlanID,
335			Terms:           termsOf(plan),
336			EffectivePeriod: nextMonth(MonthOf(now)),
337		}
338		acc.sub.pending = &change
339		return PlanChangeResult{Created: true, Change: change}, nil
340	}
341	
342	// CancelPlanChange 在安排生效前取消它，取消后账户继续沿用当前套餐。
343	// 没有待生效安排时取消也成功；已生效的切换不会被撤回。
344	// 欠费停用期间也可以取消，取消不清除欠费、不解除停用。
345	// 账户不存在、订阅已终止（含已到终止时刻）时失败。
346	func (s *Service) CancelPlanChange(accountID string) error {
347		if accountID == "" {
348			return invalidf("account id is empty")
349		}
350		s.mu.Lock()
351		defer s.mu.Unlock()
352		acc, ok := s.accounts[accountID]
353		if !ok {
354			return ErrAccountNotFound
355		}
356		// 已到生效月份月初零点的安排视为已生效，不可撤回；已终止订阅段无当前订阅。
357		s.settleLocked(acc, s.nowUTC())
358		if acc.sub == nil {
359			return ErrSubscriptionNotFound
360		}
361		acc.sub.pending = nil
362		return nil
363	}
364	
365	// CancelSubscription 为当前有效订阅登记按月取消。
366	//
367	// 仅当订阅已生效（当前时刻不早于开通时刻）时可取消；欠费停用不妨碍取消，也不
368	// 免除债务。终止时刻为请求时刻的下一个 UTC 自然月月初零点（UTC）：当月照常
369	// 接收用量并按完整月费与额度计费，不按天退款。重复取消始终返回原终止时刻，
370	// 不把期限后移（Cancelled 为 false）。
371	//
372	// 成功时清除尚未生效的换套餐安排；若请求恰在某次换套餐生效的月初，先承认该次
373	// 切换，取消从再下一月生效。等待取消期间拒绝新的换套餐安排。
374	//
375	// 账户不存在、从未开通或当前无有效订阅、开通时刻尚未到达时请求失败。
376	func (s *Service) CancelSubscription(accountID string) (CancelSubscriptionResult, error) {
377		if accountID == "" {
378			return CancelSubscriptionResult{}, invalidf("account id is empty")
379		}
380		s.mu.Lock()
381		defer s.mu.Unlock()
382	
383		acc, ok := s.accounts[accountID]
384		if !ok {
385			return CancelSubscriptionResult{}, ErrAccountNotFound
386		}
387		now := s.nowUTC()
388		// 先补齐到期状态：恰在月初时先承认到期换套餐，终止时刻取再下一月。
389		s.settleLocked(acc, now)
390		if acc.sub == nil {
391			return CancelSubscriptionResult{}, ErrSubscriptionNotFound
392		}
393		if now.Before(acc.sub.activatedAt) {
394			return CancelSubscriptionResult{}, ErrSubscriptionNotActivated
395		}
396	
397		// 重复取消：原样返回原终止时刻，不后移期限。
398		if acc.sub.cancelEnd != nil {
399			return CancelSubscriptionResult{
400				Cancelled:    false,
401				Cancellation: SubscriptionCancellation{EndAt: *acc.sub.cancelEnd},
402			}, nil
403		}
404	
405		// 登记取消清除尚未生效的换套餐安排（撤回取消也不恢复它）。
406		acc.sub.pending = nil
407		end := nextMonth(MonthOf(now)).Start()
408		acc.sub.cancelEnd = &end
409		return CancelSubscriptionResult{
410			Cancelled:    true,
411			Cancellation: SubscriptionCancellation{EndAt: end},
412		}, nil
413	}
414	
415	// UndoCancelSubscription 在取消生效前撤回按月取消安排，撤回后订阅继续有效。
416	// 有效订阅没有取消安排时撤回也成功；撤回不恢复登记取消时被清除的换套餐安排。
417	// 终止时刻已到（订阅已终止）后撤回失败（ErrSubscriptionNotFound）；
418	// 账户不存在或从未开通时同样失败。
419	func (s *Service) UndoCancelSubscription(accountID string) error {
420		if accountID == "" {
421			return invalidf("account id is empty")
422		}
423		s.mu.Lock()
424		defer s.mu.Unlock()
425		acc, ok := s.accounts[accountID]
426		if !ok {
427			return ErrAccountNotFound
428		}
429		// 到达终止时刻后订阅已终止：撤回失败。
430		s.settleLocked(acc, s.nowUTC())
431		if acc.sub == nil {
432			return ErrSubscriptionNotFound
433		}
434		acc.sub.cancelEnd = nil
435		return nil
436	}
437	
438	// RecordEvent 上报一条用量事件。
439	//
440	// 事件按发生时刻归入 UTC 自然月账期；事件发生时刻必须属于某段实际订阅期间
441	// （开通时刻计入、终止时刻不计入），空档期间与晚于当前时刻的事件被拒绝。
442	// 订阅终止后仍可补报旧订阅期间且尚未出账的用量。
443	// 事件标识在同一账户内去重：完全相同的重报返回原结果且不重复累计——
444	// 即使发生在取消、重新开通之后也成功；相同标识但时刻或数量不同返回
445	// ErrEventConflict。
446	// 已出账月份拒绝新事件；账户因到期欠费停用时拒绝新增事件；
447	// 但此前已接收事件的完全相同重报始终成功。
448	func (s *Service) RecordEvent(e Event) (EventResult, error) {
449		if e.AccountID == "" {
450			return EventResult{}, invalidf("account id is empty")
451		}
452		if e.EventID == "" {
453			return EventResult{}, invalidf("event id is empty")
454		}
455		if e.Quantity < 0 {
456			return EventResult{}, invalidf("event %q has negative quantity %d", e.EventID, e.Quantity)
457		}
458		if e.At.IsZero() {
459			return EventResult{}, invalidf("event %q has zero timestamp", e.EventID)
460		}
461		at := e.At.UTC()
462	
463		s.mu.Lock()
464		defer s.mu.Unlock()
465	
466		acc, ok := s.accounts[e.AccountID]
467		if !ok {
468			return EventResult{}, ErrAccountNotFound
469		}
470	
471		now := s.nowUTC()
472		// 进入即补齐已到期的换套餐/取消，保证并发下各操作观察到一致的分段状态。
473		s.settleLocked(acc, now)
474	
475		// 从未开通订阅的账户没有任何订阅段。
476		if acc.sub == nil && len(acc.history) == 0 {
477			return EventResult{}, ErrSubscriptionNotFound
478		}
479	
480		// 去重优先：完全相同的重报即使发生在出账后、停用期间、取消或重新开通
481		// 之后也返回成功。
482		if prev, ok := acc.events[e.EventID]; ok {
483			if !prev.at.Equal(at) || prev.qty != e.Quantity {
484				return EventResult{}, ErrEventConflict
485			}
486			return EventResult{Accepted: false, Period: prev.period}, nil
487		}
488	
489		if at.After(now) {
490			return EventResult{}, ErrEventInFuture
491		}
492		// 事件发生时刻必须落在某段实际订阅期间：[activatedAt, end)。
493		if activeSegmentAtLocked(acc, at) == nil {
494			return EventResult{}, ErrEventBeforeSubscription
495		}
496	
497		period := MonthOf(at)
498		if _, billed := acc.bills[period]; billed {
499			return EventResult{}, ErrMonthBilled
500		}
501		if s.isSuspendedLocked(acc, now) {
502			return EventResult{}, ErrSuspended
503		}
504	
505		total, ok := addNonNeg(acc.usage[period], e.Quantity)
506		if !ok {
507			return EventResult{}, ErrOverflow
508		}
509		// 所有校验通过后才落库：失败不消耗事件标识。
510		acc.events[e.EventID] = eventRecord{at: at, qty: e.Quantity, period: period}
511		acc.usage[period] = total
512		return EventResult{Accepted: true, Period: period}, nil
513	}
514	
515	// CreateBill 为账户指定账期生成账单（账期不存在则幂等返回同一张）。
516	// 只能为某段订阅实际覆盖的、且已经结束的月份生成账单：开通当月计入、终止
517	// 当月（终止时刻所在月）不计入该段，完全无订阅的空档月份出账失败。
518	// 取消订阅不自动出账；终止后旧订阅覆盖的已结束月份仍可出账，使用各月当时
519	// 锁定的条件。重复调用得到同一账单；出账后金额与用量明细固定。
520	func (s *Service) CreateBill(accountID string, period Month) (Bill, error) {
521		if accountID == "" {
522			return Bill{}, invalidf("account id is empty")
523		}
524		if period.Month < time.January || period.Month > time.December {
525			return Bill{}, invalidf("invalid billing period %d-%d", period.Year, period.Month)
526		}
527		s.mu.Lock()
528		defer s.mu.Unlock()
529	
530		acc, ok := s.accounts[accountID]
531		if !ok {
532			return Bill{}, ErrAccountNotFound
533		}
534		if existing, ok := acc.bills[period]; ok {
535			return existing.bill, nil
536		}
537	
538		now := s.nowUTC()
539		// 补齐到期换套餐/取消（条件历史与分段），随后按账期取覆盖该月的订阅段中
540		// 当时适用的条件：即使已重新开通或先出新月份账单再补旧月份账单，历史账单
541		// 也不会被后来的订阅覆盖。
542		s.settleLocked(acc, now)
543	
544		if acc.sub == nil && len(acc.history) == 0 {
545			return Bill{}, ErrSubscriptionNotFound
546		}
547		if period.End().After(now) {
548			return Bill{}, ErrBillMonthNotEnded
549		}
550	
551		sub := segmentForBillingLocked(acc, period)
552		if sub == nil {
553			// 早于首段开通，或处于两段订阅之间的空档。
554			return Bill{}, ErrBillBeforeSubscription
555		}
556	
557		terms := termsForPeriod(sub, period)
558		bill, err := buildBill(accountID, period, terms, acc.usage[period])
559		if err != nil {
560			return Bill{}, err
561		}
562		acc.bills[period] = &billRecord{bill: bill}
563		return bill, nil
564	}
565	
566	// GetBill 返回指定账期的账单；尚未出账返回 ErrBillNotFound。
567	func (s *Service) GetBill(accountID string, period Month) (Bill, error) {
568		if accountID == "" {
569			return Bill{}, invalidf("account id is empty")
570		}
571		s.mu.Lock()
572		defer s.mu.Unlock()
573		acc, ok := s.accounts[accountID]
574		if !ok {
575			return Bill{}, ErrAccountNotFound
576		}
577		rec, ok := acc.bills[period]
578		if !ok {
579			return Bill{}, ErrBillNotFound
580		}
581		return rec.bill, nil
582	}
583	
584	// RecordPayment 为指定账单登记一笔大于零且不超过余额的本地付款，支持分次登记。
585	// 付款标识在同一账户内去重：相同账单和金额的重报返回原结果，
586	// 改成其他账单或金额返回 ErrPaymentConflict；失败不消耗付款标识。
587	func (s *Service) RecordPayment(accountID, paymentID string, period Month, amount int64) (PaymentResult, error) {
588		if accountID == "" {
589			return PaymentResult{}, invalidf("account id is empty")
590		}
591		if paymentID == "" {
592			return PaymentResult{}, invalidf("payment id is empty")
593		}
594		if amount <= 0 {
595			return PaymentResult{}, invalidf("payment %q amount must be positive, got %d", paymentID, amount)
596		}
597		s.mu.Lock()
598		defer s.mu.Unlock()
599	
600		acc, ok := s.accounts[accountID]
601		if !ok {
602			return PaymentResult{}, ErrAccountNotFound
603		}
604		// 去重先于账单查找：相同标识改指向其他账单（哪怕不存在）也是冲突。
605		if prev, ok := acc.payments[paymentID]; ok {
606			if prev.period != period || prev.amount != amount {
607				return PaymentResult{}, ErrPaymentConflict
608			}
609			rec, ok := acc.bills[period]
610			if !ok {
611				return PaymentResult{}, ErrBillNotFound
612			}
613			return PaymentResult{
614				Registered:  false,
615				Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
616				BillBalance: rec.bill.Balance,
617				Settled:     rec.bill.Settled,
618			}, nil
619		}
620	
621		rec, ok := acc.bills[period]
622		if !ok {
623			return PaymentResult{}, ErrBillNotFound
624		}
625	
626		if amount > rec.bill.Balance {
627			return PaymentResult{}, ErrPaymentExceedsBalance
628		}
629	
630		paid, ok := addNonNeg(rec.bill.Paid, amount)
631		if !ok {
632			return PaymentResult{}, ErrOverflow
633		}
634		rec.bill.Paid = paid
635		rec.bill.Balance -= amount
636		if rec.bill.Balance == 0 {
637			rec.bill.Settled = true
638		}
639		acc.payments[paymentID] = paymentRecord{period: period, amount: amount}
640	
641		return PaymentResult{
642			Registered:  true,
643			Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
644			BillBalance: rec.bill.Balance,
645			Settled:     rec.bill.Settled,
646		}, nil
647	}
648	
649	// MonthlyUsage 返回账户某账期的累计用量；无任何用量时返回 0。
650	func (s *Service) MonthlyUsage(accountID string, period Month) (Usage, error) {
651		if accountID == "" {
652			return Usage{}, invalidf("account id is empty")
653		}
654		s.mu.Lock()
655		defer s.mu.Unlock()
656		acc, ok := s.accounts[accountID]
657		if !ok {
658			return Usage{}, ErrAccountNotFound
659		}
660		// 与其他入口保持一致：顺带让已到期的换套餐/取消生效。
661		s.settleLocked(acc, s.nowUTC())
662		return Usage{Period: period, Total: acc.usage[period]}, nil
663	}
664	
665	// Status 返回账户状态：各月累计用量、各账单余额以及当前是否因欠费停用。
666	func (s *Service) Status(accountID string) (AccountStatus, error) {
667		if accountID == "" {
668			return AccountStatus{}, invalidf("account id is empty")
669		}
670		s.mu.Lock()
671		defer s.mu.Unlock()
672		acc, ok := s.accounts[accountID]
673		if !ok {
674			return AccountStatus{}, ErrAccountNotFound
675		}
676	
677		now := s.nowUTC()
678		// 查询即让已到期安排/取消生效：月初零点或终止时刻之后无需上报用量或出账，
679		// 当前条件与订阅状态立即更新。
680		s.settleLocked(acc, now)
681	
682		periodSet := make(map[Month]struct{}, len(acc.usage)+len(acc.bills))
683		for m := range acc.usage {
684			periodSet[m] = struct{}{}
685		}
686		for m := range acc.bills {
687			periodSet[m] = struct{}{}
688		}
689		periods := make([]Month, 0, len(periodSet))
690		for m := range periodSet {
691			periods = append(periods, m)
692		}
693		sortMonths(periods)
694	
695		st := AccountStatus{
696			AccountID:    accountID,
697			Subscribed:   acc.sub != nil,
698			Suspended:    s.isSuspendedLocked(acc, now),
699			MonthlyUsage: make([]Usage, 0, len(periods)),
700			Bills:        make([]BillSummary, 0, len(acc.bills)),
701		}
702		if acc.sub != nil {
703			st.CurrentTerms = acc.sub.terms
704			if acc.sub.pending != nil {
705				pending := *acc.sub.pending
706				st.PendingChange = &pending
707			}
708			if acc.sub.cancelEnd != nil {
709				end := *acc.sub.cancelEnd
710				st.ScheduledEnd = &end
711			}
712		}
713		for _, m := range periods {
714			st.MonthlyUsage = append(st.MonthlyUsage, Usage{Period: m, Total: acc.usage[m]})
715		}
716		for _, m := range periods {
717			if rec, ok := acc.bills[m]; ok {
718				b := rec.bill
719				st.Bills = append(st.Bills, BillSummary{
720					Period:   m,
721					TotalDue: b.TotalDue,
722					Paid:     b.Paid,
723					Balance:  b.Balance,
724					Settled:  b.Settled,
725					DueAt:    b.DueAt,
726				})
727			}
728		}
729		return st, nil
730	}
731	
732	// isSuspendedLocked 报告账户当前是否停用：
733	// 存在到达付款截止时刻仍有余额的账单。调用时持有 s.mu。
734	func (s *Service) isSuspendedLocked(acc *account, now time.Time) bool {
735		for _, rec := range acc.bills {
736			if !rec.bill.Settled && !now.Before(rec.bill.DueAt) {
737				return true
738			}
739		}
740		return false
741	}
742	
743	func sortMonths(ms []Month) {
744		sort.Slice(ms, func(i, j int) bool { return ms[i].Before(ms[j]) })
745	}
746	
747	// addNonNeg 返回两个非负 int64 之和；溢出时 ok=false。
748	func addNonNeg(a, b int64) (int64, bool) {
749		if a > maxInt64-b {
750			return 0, false
751		}
752		return a + b, true
753	}
754	
755	// mulNonNeg 返回两个非负 int64 之积；溢出时 ok=false。
756	func mulNonNeg(a, b int64) (int64, bool) {
757		if a == 0 || b == 0 {
758			return 0, true
759		}
760		if a > maxInt64/b {
761			return 0, false
762		}
763		return a * b, true
764	}
765	
766	// buildBill 依据套餐快照和账期总用量计算账单，所有金额运算做溢出检查。
767	func buildBill(accountID string, period Month, t PlanTerms, totalUsage int64) (Bill, error) {
768		overageUnits := int64(0)
769		if totalUsage > t.IncludedUnits {
770			overageUnits = totalUsage - t.IncludedUnits
771		}
772		overageFee, ok := mulNonNeg(overageUnits, t.OveragePrice)
773		if !ok {
774			return Bill{}, ErrOverflow
775		}
776		subtotal, ok := addNonNeg(t.MonthlyFee, overageFee)
777		if !ok {
778			return Bill{}, ErrOverflow
779		}
780		tax, ok := rateAmount(subtotal, t.TaxRateBasisPoints)
781		if !ok {
782			return Bill{}, ErrOverflow
783		}
784		totalDue, ok := addNonNeg(subtotal, tax)
785		if !ok {
786			return Bill{}, ErrOverflow
787		}
788		b := Bill{
789			AccountID:     accountID,
790			Period:        period,
791			Terms:         t,
792			TotalUsage:    totalUsage,
793			IncludedUnits: t.IncludedUnits,
794			OverageUnits:  overageUnits,
795			MonthlyFee:    t.MonthlyFee,
796			OverageFee:    overageFee,
797			Tax:           tax,
798			TotalDue:      totalDue,
799			Paid:          0,
800			Balance:       totalDue,
801			Settled:       totalDue == 0,
802			DueAt:         period.End().AddDate(0, 0, 7),
803		}
804		return b, nil
805	}
806	
807	// rateAmount 计算 amount*rate/10000 并四舍五入到分（非负数，半数向上）。
808	// 拆分商和余数计算以避免乘积溢出 int64。
809	func rateAmount(amount, rate int64) (int64, bool) {
810		const den = 10000
811		q, r := amount/den, amount%den
812		qr, ok := mulNonNeg(q, rate)
813		if !ok {
814			return 0, false
815		}
816		rr, ok := mulNonNeg(r, rate)
817		if !ok {
818			return 0, false
819		}
820		// 四舍五入：(rr + den/2) / den，rr < den*10001 < 1e8，加 den/2 不溢出。
821		add, ok := addNonNeg(qr, (rr+den/2)/den)
822		if !ok {
823			return 0, false
824		}
825		return add, true
826	}
827

